def transform(grid):
    counts = Counter(v for row in grid for v in row)
    common = [v for v, _ in counts.most_common(2)]
    fill = common[0]
    markers = [(r, c, grid[r][c])
               for r in range(len(grid)) for c in range(len(grid[0]))
               if grid[r][c] not in common]
    rows = sorted({r for r, c, v in markers})
    cols = sorted({c for r, c, v in markers})
    out = [[fill for _ in range(len(cols)-1)] for _ in range(len(rows)-1)]
    for i in range(len(rows)-1):
        for j in range(len(cols)-1):
            corners = [grid[rows[i]][cols[j]], grid[rows[i]][cols[j+1]],
                       grid[rows[i+1]][cols[j]], grid[rows[i+1]][cols[j+1]]]
            if corners[0] not in common and all(v == corners[0] for v in corners):
                out[i][j] = corners[0]
    return out
